Here's a complete, self-contained Account Settings screen for a React Native (iOS + Android) app. It uses only core RN components (no extra deps), supports light theming out of the box, and gates account deletion behind a type-to-confirm modal with loading/error states.

```tsx
// AccountSettingsScreen.tsx
import React, { useCallback, useMemo, useState } from 'react';
import {
  ActivityIndicator,
  Alert,
  Image,
  KeyboardAvoidingView,
  Modal,
  Platform,
  Pressable,
  ScrollView,
  StyleSheet,
  Switch,
  Text,
  TextInput,
  TouchableOpacity,
  View,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface AccountUser {
  name: string;
  email: string;
  avatarUrl?: string;
}

type NavRow = {
  type: 'nav';
  key: string;
  label: string;
  value?: string;
};

type ToggleRow = {
  type: 'toggle';
  key: string;
  label: string;
};

type DangerRow = {
  type: 'danger';
  key: string;
  label: string;
};

type SettingRow = NavRow | ToggleRow | DangerRow;

interface Section {
  title?: string;
  rows: SettingRow[];
}

export interface AccountSettingsScreenProps {
  user: AccountUser;
  /** Initial values for toggle rows, keyed by row key. */
  initialToggles?: Record<string, boolean>;
  onEditProfile?: () => void;
  /** Called when a nav-type row is tapped (key matches the row's `key`). */
  onNavigate?: (key: string) => void;
  /** Called when a toggle row changes. */
  onToggleChange?: (key: string, value: boolean) => void;
  /** Must resolve on success, or throw/reject with an Error on failure. */
  onDeleteAccount: () => Promise<void>;
  /** Called after the account is successfully deleted (e.g. to sign the user out). */
  onDeleted?: () => void;
}

// ---------------------------------------------------------------------------
// Static section config
// ---------------------------------------------------------------------------

const SECTIONS: Section[] = [
  {
    title: 'Account',
    rows: [
      { type: 'nav', key: 'editProfile', label: 'Edit Profile' },
      { type: 'nav', key: 'changePassword', label: 'Change Password' },
      { type: 'nav', key: 'linkedAccounts', label: 'Linked Accounts' },
    ],
  },
  {
    title: 'Preferences',
    rows: [
      { type: 'toggle', key: 'pushNotifications', label: 'Push Notifications' },
      { type: 'toggle', key: 'emailNotifications', label: 'Email Notifications' },
      { type: 'toggle', key: 'darkMode', label: 'Dark Mode' },
    ],
  },
  {
    title: 'Support',
    rows: [
      { type: 'nav', key: 'helpCenter', label: 'Help Center' },
      { type: 'nav', key: 'contactUs', label: 'Contact Us' },
      { type: 'nav', key: 'termsPrivacy', label: 'Terms & Privacy' },
    ],
  },
  {
    title: 'Danger Zone',
    rows: [{ type: 'danger', key: 'deleteAccount', label: 'Delete Account' }],
  },
];

const DELETE_CONFIRM_WORD = 'DELETE';

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

export default function AccountSettingsScreen({
  user,
  initialToggles,
  onEditProfile,
  onNavigate,
  onToggleChange,
  onDeleteAccount,
  onDeleted,
}: AccountSettingsScreenProps) {
  const [toggles, setToggles] = useState<Record<string, boolean>>({
    pushNotifications: true,
    emailNotifications: true,
    darkMode: false,
    ...initialToggles,
  });

  const [deleteModalVisible, setDeleteModalVisible] = useState(false);
  const [confirmText, setConfirmText] = useState('');
  const [isDeleting, setIsDeleting] = useState(false);
  const [deleteError, setDeleteError] = useState<string | null>(null);

  const handleToggle = useCallback(
    (key: string, value: boolean) => {
      setToggles((prev) => ({ ...prev, [key]: value }));
      onToggleChange?.(key, value);
    },
    [onToggleChange]
  );

  const openDeleteModal = useCallback(() => {
    setConfirmText('');
    setDeleteError(null);
    setDeleteModalVisible(true);
  }, []);

  const closeDeleteModal = useCallback(() => {
    if (isDeleting) return; // don't allow dismiss mid-request
    setDeleteModalVisible(false);
  }, [isDeleting]);

  const canConfirmDelete = confirmText.trim() === DELETE_CONFIRM_WORD && !isDeleting;

  const handleConfirmDelete = useCallback(async () => {
    if (!canConfirmDelete) return;
    setIsDeleting(true);
    setDeleteError(null);
    try {
      await onDeleteAccount();
      setDeleteModalVisible(false);
      onDeleted?.();
    } catch (err) {
      setDeleteError(
        err instanceof Error ? err.message : 'Something went wrong. Please try again.'
      );
    } finally {
      setIsDeleting(false);
    }
  }, [canConfirmDelete, onDeleteAccount, onDeleted]);

  const handleRowPress = useCallback(
    (row: SettingRow) => {
      if (row.type === 'danger') {
        openDeleteModal();
        return;
      }
      if (row.type === 'nav') {
        onNavigate?.(row.key);
      }
    },
    [onNavigate, openDeleteModal]
  );

  const initials = useMemo(() => getInitials(user.name), [user.name]);

  return (
    <SafeAreaView style={styles.safeArea} edges={['top', 'bottom']}>
      <ScrollView
        contentContainerStyle={styles.scrollContent}
        showsVerticalScrollIndicator={false}
      >
        {/* Profile row */}
        <TouchableOpacity
          style={styles.profileCard}
          onPress={onEditProfile}
          accessibilityRole="button"
          accessibilityLabel={`${user.name}, ${user.email}. Edit profile`}
          testID="profile-row"
        >
          {user.avatarUrl ? (
            <Image source={{ uri: user.avatarUrl }} style={styles.avatar} />
          ) : (
            <View style={[styles.avatar, styles.avatarFallback]}>
              <Text style={styles.avatarInitials}>{initials}</Text>
            </View>
          )}
          <View style={styles.profileText}>
            <Text style={styles.profileName} numberOfLines={1}>
              {user.name}
            </Text>
            <Text style={styles.profileEmail} numberOfLines={1}>
              {user.email}
            </Text>
          </View>
          <Text style={styles.chevron}>{'\u203A'}</Text>
        </TouchableOpacity>

        {/* Settings sections */}
        {SECTIONS.map((section) => (
          <View key={section.title ?? 'untitled'} style={styles.section}>
            {section.title ? (
              <Text style={styles.sectionTitle}>{section.title.toUpperCase()}</Text>
            ) : null}
            <View style={styles.card}>
              {section.rows.map((row, index) => (
                <SettingsRow
                  key={row.key}
                  row={row}
                  isLast={index === section.rows.length - 1}
                  toggleValue={row.type === 'toggle' ? toggles[row.key] : undefined}
                  onToggle={handleToggle}
                  onPress={handleRowPress}
                />
              ))}
            </View>
          </View>
        ))}
      </ScrollView>

      <DeleteAccountModal
        visible={deleteModalVisible}
        confirmText={confirmText}
        onChangeConfirmText={setConfirmText}
        canConfirm={canConfirmDelete}
        isDeleting={isDeleting}
        error={deleteError}
        onCancel={closeDeleteModal}
        onConfirm={handleConfirmDelete}
      />
    </SafeAreaView>
  );
}

// ---------------------------------------------------------------------------
// Row renderer
// ---------------------------------------------------------------------------

interface SettingsRowProps {
  row: SettingRow;
  isLast: boolean;
  toggleValue?: boolean;
  onToggle: (key: string, value: boolean) => void;
  onPress: (row: SettingRow) => void;
}

function SettingsRow({ row, isLast, toggleValue, onToggle, onPress }: SettingsRowProps) {
  const labelStyle = row.type === 'danger' ? styles.dangerLabel : styles.rowLabel;

  if (row.type === 'toggle') {
    return (
      <View style={[styles.row, !isLast && styles.rowDivider]} testID={`row-${row.key}`}>
        <Text style={labelStyle}>{row.label}</Text>
        <Switch
          value={!!toggleValue}
          onValueChange={(value) => onToggle(row.key, value)}
          accessibilityRole="switch"
          accessibilityLabel={row.label}
          accessibilityState={{ checked: !!toggleValue }}
        />
      </View>
    );
  }

  return (
    <TouchableOpacity
      style={[styles.row, !isLast && styles.rowDivider]}
      onPress={() => onPress(row)}
      accessibilityRole="button"
      accessibilityLabel={row.label}
      testID={`row-${row.key}`}
    >
      <Text style={labelStyle}>{row.label}</Text>
      {row.type === 'nav' && (
        <View style={styles.rowTrailing}>
          {row.value ? <Text style={styles.rowValue}>{row.value}</Text> : null}
          <Text style={styles.chevron}>{'\u203A'}</Text>
        </View>
      )}
    </TouchableOpacity>
  );
}

// ---------------------------------------------------------------------------
// Delete confirmation modal
// ---------------------------------------------------------------------------

interface DeleteAccountModalProps {
  visible: boolean;
  confirmText: string;
  onChangeConfirmText: (text: string) => void;
  canConfirm: boolean;
  isDeleting: boolean;
  error: string | null;
  onCancel: () => void;
  onConfirm: () => void;
}

function DeleteAccountModal({
  visible,
  confirmText,
  onChangeConfirmText,
  canConfirm,
  isDeleting,
  error,
  onCancel,
  onConfirm,
}: DeleteAccountModalProps) {
  return (
    <Modal
      visible={visible}
      transparent
      animationType="fade"
      onRequestClose={onCancel}
      statusBarTranslucent
    >
      <KeyboardAvoidingView
        style={styles.modalOverlay}
        behavior={Platform.OS === 'ios' ? 'padding' : undefined}
      >
        <Pressable style={styles.modalBackdrop} onPress={onCancel} />
        <View style={styles.modalCard}>
          <Text style={styles.modalTitle}>Delete your account?</Text>
          <Text style={styles.modalBody}>
            This will permanently delete your account and all associated data. This action
            cannot be undone.
          </Text>
          <Text style={styles.modalInstruction}>
            Type <Text style={styles.modalInstructionBold}>{DELETE_CONFIRM_WORD}</Text> to
            confirm.
          </Text>
          <TextInput
            value={confirmText}
            onChangeText={onChangeConfirmText}
            placeholder={DELETE_CONFIRM_WORD}
            placeholderTextColor="#B0B0B5"
            autoCapitalize="characters"
            autoCorrect={false}
            autoFocus
            editable={!isDeleting}
            style={styles.modalInput}
            accessibilityLabel="Type DELETE to confirm account deletion"
            testID="delete-confirm-input"
          />
          {error ? <Text style={styles.modalError}>{error}</Text> : null}

          <View style={styles.modalActions}>
            <TouchableOpacity
              style={[styles.modalButton, styles.modalButtonSecondary]}
              onPress={onCancel}
              disabled={isDeleting}
              testID="delete-cancel-button"
            >
              <Text style={styles.modalButtonSecondaryText}>Cancel</Text>
            </TouchableOpacity>
            <TouchableOpacity
              style={[
                styles.modalButton,
                styles.modalButtonDanger,
                !canConfirm && styles.modalButtonDisabled,
              ]}
              onPress={onConfirm}
              disabled={!canConfirm}
              testID="delete-confirm-button"
            >
              {isDeleting ? (
                <ActivityIndicator color="#FFFFFF" />
              ) : (
                <Text style={styles.modalButtonDangerText}>Delete Account</Text>
              )}
            </TouchableOpacity>
          </View>
        </View>
      </KeyboardAvoidingView>
    </Modal>
  );
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function getInitials(name: string): string {
  const parts = name.trim().split(/\s+/).filter(Boolean);
  if (parts.length === 0) return '?';
  if (parts.length === 1) return parts[0][0]?.toUpperCase() ?? '?';
  return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
}

// ---------------------------------------------------------------------------
